import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import { format } from "prettier";
const root = resolve(import.meta.dirname, "..");
const palette = JSON.parse(
  await readFile(resolve(root, "branding/palette.json"), "utf8"),
);
const kebab = (s) => s.replace(/[A-Z]/g, (x) => "-" + x.toLowerCase());
let css =
  "/* Generated by scripts/sync-brand-theme.mjs from branding/palette.json. */\n:root {\n";
for (const [key, value] of Object.entries(palette))
  css += `  --brand-${kebab(key)}: ${value};\n`;
css += "  --brand-navy-rgb: 25 58 78;\n}\n";
await writeFile(resolve(root, "web/app/brand-tokens.css"), css);
await writeFile(
  resolve(root, "mobile/theme.ts"),
  await format(
    "// Generated from branding/palette.json. Run node scripts/sync-brand-theme.mjs.\nexport const theme = " +
      JSON.stringify(palette, null, 2) +
      " as const;\n",
    { parser: "typescript" },
  ),
);
await writeFile(
  resolve(root, "mobile/brand-config.json"),
  JSON.stringify(palette, null, 2) + "\n",
);
console.log("Palette EduBest synchronisée sur le web et le mobile.");
